1	import {
2	  HttpStatus,
3	  Injectable,
4	  NotFoundException,
5	  UnauthorizedException,
6	  UnprocessableEntityException,
7	} from '@nestjs/common';
8	import ms from 'ms';
9	import crypto from 'crypto';
10	import { randomStringGenerator } from '@nestjs/common/utils/random-string-generator.util';
11	import { JwtService } from '@nestjs/jwt';
12	import bcrypt from 'bcryptjs';
13	import { AuthEmailLoginDto } from './dto/auth-email-login.dto';
14	import { AuthUpdateDto } from './dto/auth-update.dto';
15	import { AuthProvidersEnum } from './auth-providers.enum';
16	import { SocialInterface } from '../social/interfaces/social.interface';
17	import { AuthRegisterLoginDto } from './dto/auth-register-login.dto';
18	import { NullableType } from '../utils/types/nullable.type';
19	import { LoginResponseDto } from './dto/login-response.dto';
20	import { ConfigService } from '@nestjs/config';
21	import { JwtRefreshPayloadType } from './strategies/types/jwt-refresh-payload.type';
22	import { JwtPayloadType } from './strategies/types/jwt-payload.type';
23	import { UsersService } from '../users/users.service';
24	import { AllConfigType } from '../config/config.type';
25	import { MailService } from '../mail/mail.service';
26	import { RoleEnum } from '../roles/roles.enum';
27	import { Session } from '../session/domain/session';
28	import { SessionService } from '../session/session.service';
29	import { StatusEnum } from '../statuses/statuses.enum';
30	import { User } from '../users/domain/user';
31	
32	@Injectable()
33	export class AuthService {
34	  constructor(
35	    private readonly jwtService: JwtService,
36	    private readonly usersService: UsersService,
37	    private readonly sessionService: SessionService,
38	    private readonly mailService: MailService,
39	    private readonly configService: ConfigService<AllConfigType>,
40	  ) {}
41	
42	  async validateLogin(loginDto: AuthEmailLoginDto): Promise<LoginResponseDto> {
43	    const user = await this.usersService.findByEmail(loginDto.email);
44	
45	    if (!user) {
46	      throw this.invalidLoginException({
47	        email: 'notFound',
48	      });
49	    }
50	
51	    if (user.provider !== AuthProvidersEnum.email) {
52	      throw this.invalidLoginException({
53	        email: `needLoginViaProvider:${user.provider}`,
54	      });
55	    }
56	
57	    if (!user.password) {
58	      throw this.invalidLoginException({
59	        password: 'incorrectPassword',
60	      });
61	    }
62	
63	    const isValidPassword = await bcrypt.compare(
64	      loginDto.password,
65	      user.password,
66	    );
67	
68	    if (!isValidPassword) {
69	      throw this.invalidLoginException({
70	        password: 'incorrectPassword',
71	      });
72	    }
73	
74	    const hash = crypto
75	      .createHash('sha256')
76	      .update(randomStringGenerator())
77	      .digest('hex');
78	
79	    const session = await this.sessionService.create({
80	      user,
81	      hash,
82	    });
83	
84	    const { token, refreshToken, tokenExpires } = await this.getTokensData({
85	      id: user.id,
86	      role: user.role,
87	      sessionId: session.id,
88	      hash,
89	    });
90	
91	    return {
92	      refreshToken,
93	      token,
94	      tokenExpires,
95	      user,
96	    };
97	  }
98	
99	  async validateSocialLogin(
100	    authProvider: string,
101	    socialData: SocialInterface,
102	  ): Promise<LoginResponseDto> {
103	    let user: NullableType<User> = null;
104	    const socialEmail = socialData.email?.toLowerCase();
105	    let userByEmail: NullableType<User> = null;
106	
107	    if (socialEmail && !socialData.emailVerified) {
108	      throw new UnprocessableEntityException({
109	        status: HttpStatus.UNPROCESSABLE_ENTITY,
110	        errors: {
111	          email: 'emailNotVerified',
112	        },
113	      });
114	    }
115	
116	    if (socialEmail) {
117	      userByEmail = await this.usersService.findByEmail(socialEmail);
118	    }
119	
120	    if (socialData.id) {
121	      user = await this.usersService.findBySocialIdAndProvider({
122	        socialId: socialData.id,
123	        provider: authProvider,
124	      });
125	    }
126	
127	    if (user) {
128	      if (socialEmail && !userByEmail) {
129	        user.email = socialEmail;
130	      }
131	      await this.usersService.update(user.id, user);
132	    } else if (userByEmail) {
133	      user = userByEmail;
134	
135	      if (user.status?.id?.toString() === StatusEnum.inactive.toString()) {
136	        user.provider = authProvider;
137	        user.socialId = socialData.id;
138	
139	        await this.usersService.update(user.id, user);
140	      }
141	    } else if (socialData.id) {
142	      const role = {
143	        id: RoleEnum.user,
144	      };
145	      const status = {
146	        id: StatusEnum.active,
147	      };
148	
149	      user = await this.usersService.create({
150	        email: socialEmail ?? null,
151	        firstName: socialData.firstName ?? null,
152	        lastName: socialData.lastName ?? null,
153	        socialId: socialData.id,
154	        provider: authProvider,
155	        role,
156	        status,
157	      });
158	
159	      user = await this.usersService.findById(user.id);
160	    }
161	
162	    if (!user) {
163	      throw new UnprocessableEntityException({
164	        status: HttpStatus.UNPROCESSABLE_ENTITY,
165	        errors: {
166	          user: 'userNotFound',
167	        },
168	      });
169	    }
170	
171	    const hash = crypto
172	      .createHash('sha256')
173	      .update(randomStringGenerator())
174	      .digest('hex');
175	
176	    const session = await this.sessionService.create({
177	      user,
178	      hash,
179	    });
180	
181	    const {
182	      token: jwtToken,
183	      refreshToken,
184	      tokenExpires,
185	    } = await this.getTokensData({
186	      id: user.id,
187	      role: user.role,
188	      sessionId: session.id,
189	      hash,
190	    });
191	
192	    return {
193	      refreshToken,
194	      token: jwtToken,
195	      tokenExpires,
196	      user,
197	    };
198	  }
