200	  async register(dto: AuthRegisterLoginDto): Promise<void> {
201	    const user = await this.usersService.create({
202	      ...dto,
203	      email: dto.email,
204	      role: {
205	        id: RoleEnum.user,
206	      },
207	      status: {
208	        id: StatusEnum.inactive,
209	      },
210	    });
211	
212	    const hash = await this.jwtService.signAsync(
213	      {
214	        confirmEmailUserId: user.id,
215	      },
216	      {
217	        secret: this.configService.getOrThrow('auth.confirmEmailSecret', {
218	          infer: true,
219	        }),
220	        expiresIn: this.configService.getOrThrow('auth.confirmEmailExpires', {
221	          infer: true,
222	        }),
223	      },
224	    );
225	
226	    await this.mailService.userSignUp({
227	      to: dto.email,
228	      data: {
229	        hash,
230	      },
231	    });
232	  }
