234	  async confirmEmail(hash: string): Promise<void> {
235	    let userId: User['id'];
236	
237	    try {
238	      const jwtData = await this.jwtService.verifyAsync<{
239	        confirmEmailUserId: User['id'];
240	      }>(hash, {
241	        secret: this.configService.getOrThrow('auth.confirmEmailSecret', {
242	          infer: true,
243	        }),
244	        algorithms: ['HS256'],
245	      });
246	
247	      userId = jwtData.confirmEmailUserId;
248	    } catch {
249	      throw new UnprocessableEntityException({
250	        status: HttpStatus.UNPROCESSABLE_ENTITY,
251	        errors: {
252	          hash: `invalidHash`,
253	        },
254	      });
255	    }
256	
257	    const user = await this.usersService.findById(userId);
258	
259	    if (
260	      !user ||
261	      user?.status?.id?.toString() !== StatusEnum.inactive.toString()
262	    ) {
263	      throw new NotFoundException({
264	        status: HttpStatus.NOT_FOUND,
265	        error: `notFound`,
266	      });
267	    }
268	
269	    user.status = {
270	      id: StatusEnum.active,
271	    };
272	
273	    await this.usersService.update(user.id, user);
274	  }
275	
276	  async confirmNewEmail(hash: string): Promise<void> {
277	    let userId: User['id'];
278	    let newEmail: User['email'];
279	
280	    try {
281	      const jwtData = await this.jwtService.verifyAsync<{
282	        confirmEmailUserId: User['id'];
283	        newEmail: User['email'];
284	      }>(hash, {
285	        secret: this.configService.getOrThrow('auth.confirmEmailSecret', {
286	          infer: true,
287	        }),
288	        algorithms: ['HS256'],
289	      });
290	
291	      userId = jwtData.confirmEmailUserId;
292	      newEmail = jwtData.newEmail;
293	    } catch {
294	      throw new UnprocessableEntityException({
295	        status: HttpStatus.UNPROCESSABLE_ENTITY,
296	        errors: {
297	          hash: `invalidHash`,
298	        },
299	      });
300	    }
301	
302	    const user = await this.usersService.findById(userId);
303	
304	    if (!user) {
305	      throw new NotFoundException({
306	        status: HttpStatus.NOT_FOUND,
307	        error: `notFound`,
308	      });
309	    }
310	
311	    user.email = newEmail;
312	    user.status = {
313	      id: StatusEnum.active,
314	    };
315	
316	    await this.usersService.update(user.id, user);
317	  }
