319	  async forgotPassword(email: string): Promise<void> {
320	    const user = await this.usersService.findByEmail(email);
321	
322	    if (!user) {
323	      const uniformErrors = this.configService.getOrThrow(
324	        'auth.uniformErrors',
325	        { infer: true },
326	      );
327	
328	      // With uniform errors enabled we do not reveal whether the email is
329	      // registered: respond exactly like the success case and skip the mail.
330	      if (uniformErrors) {
331	        return;
332	      }
333	
334	      throw new UnprocessableEntityException({
335	        status: HttpStatus.UNPROCESSABLE_ENTITY,
336	        errors: {
337	          email: 'emailNotExists',
338	        },
339	      });
340	    }
341	
342	    const tokenExpiresIn = this.configService.getOrThrow('auth.forgotExpires', {
343	      infer: true,
344	    });
345	
346	    const tokenExpires = Date.now() + ms(tokenExpiresIn);
347	
348	    const hash = await this.jwtService.signAsync(
349	      {
350	        forgotUserId: user.id,
351	      },
352	      {
353	        secret: this.getForgotSecret(user),
354	        expiresIn: tokenExpiresIn,
355	      },
356	    );
357	
358	    await this.mailService.forgotPassword({
359	      to: email,
360	      data: {
361	        hash,
362	        tokenExpires,
363	      },
364	    });
365	  }
366	
367	  async resetPassword(hash: string, password: string): Promise<void> {
368	    let userId: User['id'] | undefined;
369	
370	    try {
371	      const jwtData = this.jwtService.decode<{
372	        forgotUserId?: User['id'];
373	      } | null>(hash);
374	
375	      userId = jwtData?.forgotUserId;
376	    } catch {
377	      userId = undefined;
378	    }
379	
380	    let user: NullableType<User> = null;
381	
382	    if (userId !== undefined && userId !== null) {
383	      try {
384	        user = await this.usersService.findById(userId);
385	      } catch {
386	        user = null;
387	      }
388	    }
389	
390	    if (!user) {
391	      throw new UnprocessableEntityException({
392	        status: HttpStatus.UNPROCESSABLE_ENTITY,
393	        errors: {
394	          hash: `invalidHash`,
395	        },
396	      });
397	    }
398	
399	    try {
400	      await this.jwtService.verifyAsync(hash, {
401	        secret: this.getForgotSecret(user),
402	        algorithms: ['HS256'],
403	      });
404	    } catch {
405	      throw new UnprocessableEntityException({
406	        status: HttpStatus.UNPROCESSABLE_ENTITY,
407	        errors: {
408	          hash: `invalidHash`,
409	        },
410	      });
411	    }
412	
413	    user.password = password;
414	
415	    await this.sessionService.deleteByUserId({
416	      userId: user.id,
417	    });
418	
419	    await this.usersService.update(user.id, user);
420	  }
421	
422	  async me(userJwtPayload: JwtPayloadType): Promise<NullableType<User>> {
423	    return this.usersService.findById(userJwtPayload.id);
424	  }
425	
426	  async update(
427	    userJwtPayload: JwtPayloadType,
428	    userDto: AuthUpdateDto,
429	  ): Promise<NullableType<User>> {
430	    const currentUser = await this.usersService.findById(userJwtPayload.id);
431	
432	    if (!currentUser) {
433	      throw new UnprocessableEntityException({
434	        status: HttpStatus.UNPROCESSABLE_ENTITY,
435	        errors: {
436	          user: 'userNotFound',
437	        },
438	      });
439	    }
440	
441	    if (userDto.password) {
442	      if (!userDto.oldPassword) {
443	        throw new UnprocessableEntityException({
444	          status: HttpStatus.UNPROCESSABLE_ENTITY,
445	          errors: {
446	            oldPassword: 'missingOldPassword',
447	          },
448	        });
449	      }
450	
451	      if (!currentUser.password) {
452	        throw new UnprocessableEntityException({
453	          status: HttpStatus.UNPROCESSABLE_ENTITY,
454	          errors: {
455	            oldPassword: 'incorrectOldPassword',
456	          },
457	        });
458	      }
459	
460	      const isValidOldPassword = await bcrypt.compare(
461	        userDto.oldPassword,
462	        currentUser.password,
463	      );
464	
465	      if (!isValidOldPassword) {
466	        throw new UnprocessableEntityException({
467	          status: HttpStatus.UNPROCESSABLE_ENTITY,
468	          errors: {
469	            oldPassword: 'incorrectOldPassword',
470	          },
471	        });
472	      } else {
473	        await this.sessionService.deleteByUserIdWithExclude({
474	          userId: currentUser.id,
475	          excludeSessionId: userJwtPayload.sessionId,
476	        });
477	      }
478	    }
479	
480	    if (userDto.email && userDto.email !== currentUser.email) {
481	      const userByEmail = await this.usersService.findByEmail(userDto.email);
482	
483	      if (userByEmail && userByEmail.id !== currentUser.id) {
484	        throw new UnprocessableEntityException({
485	          status: HttpStatus.UNPROCESSABLE_ENTITY,
486	          errors: {
487	            email: 'emailExists',
488	          },
489	        });
490	      }
491	
492	      const hash = await this.jwtService.signAsync(
493	        {
494	          confirmEmailUserId: currentUser.id,
495	          newEmail: userDto.email,
496	        },
497	        {
498	          secret: this.configService.getOrThrow('auth.confirmEmailSecret', {
499	            infer: true,
500	          }),
501	          expiresIn: this.configService.getOrThrow('auth.confirmEmailExpires', {
502	            infer: true,
503	          }),
504	        },
505	      );
506	
507	      await this.mailService.confirmNewEmail({
508	        to: userDto.email,
509	        data: {
510	          hash,
511	        },
512	      });
513	    }
514	
515	    delete userDto.email;
516	    delete userDto.oldPassword;
517	
518	    await this.usersService.update(userJwtPayload.id, userDto);
519	
520	    return this.usersService.findById(userJwtPayload.id);
521	  }
522	
523	  async refreshToken(
524	    data: Pick<JwtRefreshPayloadType, 'sessionId' | 'hash'>,
525	  ): Promise<Omit<LoginResponseDto, 'user'>> {
526	    const hash = crypto
527	      .createHash('sha256')
528	      .update(randomStringGenerator())
529	      .digest('hex');
530	
531	    const session = await this.sessionService.updateByHash(
532	      { id: data.sessionId, hash: data.hash },
533	      { hash },
534	    );
535	
536	    if (!session) {
537	      throw new UnauthorizedException();
538	    }
539	
540	    const user = await this.usersService.findById(session.user.id);
541	
542	    if (!user?.role) {
543	      throw new UnauthorizedException();
544	    }
545	
546	    const { token, refreshToken, tokenExpires } = await this.getTokensData({
547	      id: session.user.id,
548	      role: {
549	        id: user.role.id,
550	      },
551	      sessionId: session.id,
552	      hash,
553	    });
554	
555	    return {
556	      token,
557	      refreshToken,
558	      tokenExpires,
559	    };
560	  }
561	
562	  async softDelete(userJwtPayload: JwtPayloadType): Promise<void> {
563	    await this.usersService.remove(userJwtPayload.id);
564	  }
565	
566	  async logout(data: Pick<JwtPayloadType, 'sessionId'>) {
567	    return this.sessionService.deleteById(data.sessionId);
568	  }
569	
570	  private invalidLoginException(
571	    errors: Record<string, string>,
572	  ): UnprocessableEntityException {
573	    const uniformErrors = this.configService.getOrThrow('auth.uniformErrors', {
574	      infer: true,
575	    });
576	
577	    return new UnprocessableEntityException({
578	      status: HttpStatus.UNPROCESSABLE_ENTITY,
579	      errors: uniformErrors
580	        ? {
581	            email: 'incorrectEmailOrPassword',
582	            password: 'incorrectEmailOrPassword',
583	          }
584	        : errors,
585	    });
586	  }
587	
588	  private getForgotSecret(user: User): string {
589	    // The secret embeds the current password hash, so every outstanding
590	    // reset link stops verifying as soon as the password changes — this is
591	    // what makes reset links single-use without storing anything extra.
592	    const forgotSecret = this.configService.getOrThrow('auth.forgotSecret', {
593	      infer: true,
594	    });
595	
596	    return `${forgotSecret}${user.password ?? ''}`;
597	  }
598	
599	  private async getTokensData(data: {
600	    id: User['id'];
601	    role: User['role'];
602	    sessionId: Session['id'];
603	    hash: Session['hash'];
604	  }) {
605	    const tokenExpiresIn = this.configService.getOrThrow('auth.expires', {
606	      infer: true,
607	    });
608	
609	    const tokenExpires = Date.now() + ms(tokenExpiresIn);
610	
611	    const [token, refreshToken] = await Promise.all([
612	      await this.jwtService.signAsync(
613	        {
614	          id: data.id,
615	          role: data.role,
616	          sessionId: data.sessionId,
617	        },
618	        {
619	          secret: this.configService.getOrThrow('auth.secret', { infer: true }),
620	          expiresIn: tokenExpiresIn,
621	        },
622	      ),
623	      await this.jwtService.signAsync(
624	        {
625	          sessionId: data.sessionId,
626	          hash: data.hash,
627	        },
628	        {
629	          secret: this.configService.getOrThrow('auth.refreshSecret', {
630	            infer: true,
631	          }),
632	          expiresIn: this.configService.getOrThrow('auth.refreshExpires', {
633	            infer: true,
634	          }),
635	        },
636	      ),
637	    ]);
638	
639	    return {
640	      token,
641	      refreshToken,
642	      tokenExpires,
643	    };
644	  }
645	}
