99	  async validateSocialLogin(
100	    authProvider: string,
101	    socialData: SocialInterface,
102	  ): Promise<LoginResponseDto> {
103	    let user: NullableType<User> = null;
104	    const socialEmail = socialData.email?.toLowerCase();
105	    let userByEmail: NullableType<User> = null;
106	
107	    if (socialEmail && !socialData.emailVerified) {
108	      throw new UnprocessableEntityException({
109	        status: HttpStatus.UNPROCESSABLE_ENTITY,
110	        errors: {
111	          email: 'emailNotVerified',
112	        },
113	      });
