103	    let user: NullableType<User> = null;
104	    const socialEmail = socialData.email?.toLowerCase();
105	    let userByEmail: NullableType<User> = null;
106	
107	    if (socialEmail && !socialData.emailVerified) {
108	      throw new UnprocessableEntityException({
109	        status: HttpStatus.UNPROCESSABLE_ENTITY,
110	        errors: {
111	          email: 'emailNotVerified',
112	        },
113	      });
114	    }
115	
116	    if (socialEmail) {
117	      userByEmail = await this.usersService.findByEmail(socialEmail);
118	    }
119	
120	    if (socialData.id) {
121	      user = await this.usersService.findBySocialIdAndProvider({
122	        socialId: socialData.id,
123	        provider: authProvider,
124	      });
125	    }
126	
127	    if (user) {
128	      if (socialEmail && !userByEmail) {
129	        user.email = socialEmail;
130	      }
131	      await this.usersService.update(user.id, user);
132	    } else if (userByEmail) {
133	      user = userByEmail;
134	
135	      if (user.status?.id?.toString() === StatusEnum.inactive.toString()) {
136	        user.provider = authProvider;
137	        user.socialId = socialData.id;
138	
139	        await this.usersService.update(user.id, user);
140	      }
141	    } else if (socialData.id) {
142	      const role = {
143	        id: RoleEnum.user,
144	      };
145	      const status = {
146	        id: StatusEnum.active,
147	      };
148	
149	      user = await this.usersService.create({
150	        email: socialEmail ?? null,
151	        firstName: socialData.firstName ?? null,
152	        lastName: socialData.lastName ?? null,
153	        socialId: socialData.id,
154	        provider: authProvider,
155	        role,
156	        status,
157	      });
158	
159	      user = await this.usersService.findById(user.id);
160	    }
161	
162	    if (!user) {
163	      throw new UnprocessableEntityException({
164	        status: HttpStatus.UNPROCESSABLE_ENTITY,
165	        errors: {
166	          user: 'userNotFound',
167	        },
168	      });
169	    }
170	
171	    const hash = crypto
172	      .createHash('sha256')
173	      .update(randomStringGenerator())
174	      .digest('hex');
175	
176	    const session = await this.sessionService.create({
177	      user,
178	      hash,
179	    });
180	
181	    const {
182	      token: jwtToken,
183	      refreshToken,
184	      tokenExpires,
185	    } = await this.getTokensData({
186	      id: user.id,
187	      role: user.role,
188	      sessionId: session.id,
189	      hash,
190	    });
191	
192	    return {
193	      refreshToken,
194	      token: jwtToken,
195	      tokenExpires,
196	      user,
197	    };
198	  }
