319	  async forgotPassword(email: string): Promise<void> {
320	    const user = await this.usersService.findByEmail(email);
321	
322	    if (!user) {
323	      const uniformErrors = this.configService.getOrThrow(
324	        'auth.uniformErrors',
325	        { infer: true },
326	      );
327	
328	      // With uniform errors enabled we do not reveal whether the email is
329	      // registered: respond exactly like the success case and skip the mail.
330	      if (uniformErrors) {
331	        return;
332	      }
333	
334	      throw new UnprocessableEntityException({
335	        status: HttpStatus.UNPROCESSABLE_ENTITY,
336	        errors: {
337	          email: 'emailNotExists',
338	        },
339	      });
340	    }
341	
342	    const tokenExpiresIn = this.configService.getOrThrow('auth.forgotExpires', {
343	      infer: true,
344	    });
345	
346	    const tokenExpires = Date.now() + ms(tokenExpiresIn);
347	
348	    const hash = await this.jwtService.signAsync(
349	      {
350	        forgotUserId: user.id,
351	      },
352	      {
353	        secret: this.getForgotSecret(user),
354	        expiresIn: tokenExpiresIn,
355	      },
356	    );
357	
358	    await this.mailService.forgotPassword({
359	      to: email,
360	      data: {
361	        hash,
362	        tokenExpires,
363	      },
364	    });
365	  }
